import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "../../assets/styles.css";// make sure path is correct

function Admin() {
    const navigate = useNavigate();
    const [showForgot, setShowForgot] = useState(false);
    

    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");

    const handleSubmit = (e) => {
        e.preventDefault();

        console.log("Email:", email);
        console.log("Password:", password);

        // redirect to dashboard
        //navigate("/dashboard");
    };

    return (
        <div className="login-page">

            {/* NAVBAR */}
            <div className="navbar">
                <div className="logo">Queuepert</div>

                <div className="nav-buttons">
                    <button onClick={() => navigate("/student/login")}>Back</button>
                </div>
            </div>

            {/* LOGIN BOX */}
            <div className="containerLogin">
                <h1>QueuePert</h1>
                <p className="description">
                    Administrator Login
                </p>

                <form onSubmit={handleSubmit}>

                    {/* EMAIL */}
                    <label className="input-label">Admin Account</label>
                    <input
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        required
                    />

                    {/* PASSWORD */}
                    <label className="input-label">Password</label>
                    <input
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                    />

                    {/* FORGOT PASSWORD */}
                    <div className="forgot-container">
                        <a href="#" onClick={(e) => {
                        e.preventDefault();           // prevents page reload
                        setShowForgot(!showForgot);   // toggle show/hide
                    }}>
                    Forgot password?
                    </a>
                    </div>

                    {showForgot && (
                        <div className="forgot-overlay">
                        <div className="forgot-content">
                        <p>Please contact the Technical Support Group (TSG) via Teams or proceed to their office
                             (3rd Floor, NGE Building) to reset your password.</p>
            
                    <button 
                        type="button" 
                            onClick={() => setShowForgot(false)}
                                className="action-btn"
                    >
                        Close
                    </button>
                    </div>
                    </div>
                )}
                    

                    {/* LOGIN BUTTON */}
                    <button type="submit" className="action-btn" onClick={() => navigate("/admin/dashboard")}>
                        Login
                    </button>

                </form>
            </div>
        </div>
    );
}

export default Admin;
